def transform(grid):
    h,w=len(grid),len(grid[0])
    counts={}
    for row in grid:
        for x in row: counts[x]=counts.get(x,0)+1
    bg=max(counts,key=counts.get)
    mark=min(x for x in counts if x!=bg)
    out=[row[:] for row in grid]
    for r in range(h):
        cs=[c for c in range(w) if grid[r][c]==mark]
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=3
    for c in range(w):
        rs=[r for r in range(h) if grid[r][c]==mark]
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=3
    return out
