def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        color = row[0]
        if color == bg:
            continue
        c = 0
        while c < w and row[c] == color:
            c += 1
        # Extend a left-edge bar only when the remaining suffix is all background.
        if c < w and all(v == bg for v in row[c:]):
            for j in range(c, w):
                out[r][j] = 1
    return out

